  DataLineOrNoStatement ("")
  DataLineOrNoStatement ("SELECT no_sin, sum(md_cpt)")
  DataLineOrNoStatement ("FROM SCD201_OPR_FNC     SOF,")
  DataLineOrNoStatement ("SCD202_LGN_MON     SLM,")
  DataLineOrNoStatement ("SCD108_CAT_CPT_COO SCCC")
  DataLineOrNoStatement ("WHERE SOF.CD_ETA         = 'DEBI'")
  DataLineOrNoStatement ("AND (")
  DataLineOrNoStatement ("(")
  DataLineOrNoStatement ("month(curdate()) = 12")
  DataLineOrNoStatement ("AND")
  DataLineOrNoStatement ("SOF.DT_ETA_TRI between  year(curdate()) * 10000")
  DataLineOrNoStatement ("and (year(curdate()) + 1) * 10000")
  DataLineOrNoStatement (")")
  DataLineOrNoStatement ("OR")
  DataLineOrNoStatement ("(")
  DataLineOrNoStatement ("month(curdate()) = 1")
  DataLineOrNoStatement ("AND")
  DataLineOrNoStatement ("SOF.DT_ETA_TRI between (year(curdate()) -1 ) * 10000")
  DataLineOrNoStatement ("and  year(curdate()) * 10000")
  DataLineOrNoStatement (")")
  DataLineOrNoStatement (")")
  DataLineOrNoStatement ("AND SOF.FL_CPN_GEN     = 'Y'")
  DataLineOrNoStatement ("AND SLM.NO_OPR_FNC     = SOF.NO_OPR_FNC")
  DataLineOrNoStatement ("AND SLM.CD_CAT_CPT     = SCCC.CD_CAT_CPT")
  DataLineOrNoStatement ("AND SCCC.DT_DEB       <= SOF.DT_CPT")
  DataLineOrNoStatement ("AND SCCC.DT_FIN       >= SOF.DT_CPT")
  DataLineOrNoStatement ("AND SCCC.FL_CUT        = 'Y'")
  DataLineOrNoStatement ("GROUP BY no_sin")
  DataLineOrNoStatement ("ORDER BY no_sin")
  DataLineOrNoStatement ("")
  DataLineOrNoStatement ("FORMAT EXTERNAL;")
  DataLineOrNoStatement ("EXIT;")
